# Builds the gallery files project/components/bundle.js and bundle.css, the app's
# generated files (app/ui/styles/tokens.css, app/ui/lucide-icons.js) and the local
# preview helpers (tokens.local.css, fonts.local.css) under .sciencescope-local/temp/design-system.
# The component styles have one source, app/ui/styles/components.css; bundle.css is
# that file plus the web font import and the gallery-only ds- scaffolding (gallery.css).
# Usage: python3 -I docs/design/system/build/build.py
import json, re, os, sys, pathlib, subprocess
HERE = os.path.dirname(os.path.abspath(__file__))
DS = os.path.join(HERE, '..', 'project')
ROOT = os.path.abspath(os.path.join(HERE, '..', '..', '..', '..'))
TMP = os.path.join(ROOT, '.sciencescope-local', 'temp', 'design-system')
APP_STYLES = os.path.join(ROOT, 'app', 'ui', 'styles')
APP_ICONS = os.path.join(ROOT, 'app', 'ui', 'lucide-icons.js')
FONT_IMPORT = "@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@400;500;600;700&family=Noto+Serif+SC:wght@400;600;700&family=JetBrains+Mono:wght@400;500&display=swap');"
GENERATED = 'Generated by docs/design/system/build/build.py from docs/design/system/%s. Do not edit.'
LOGO_SVG = os.path.join(HERE, '..', 'logo', 'sciencescope-mark.svg')
ORDER = [
    'Icons', 'Logo',
    'Button', 'IconButton', 'SendButton',
    'TextField', 'Select', 'Checkbox', 'SegmentedControl', 'Slider',
    'Tabs', 'Sidebar', 'PageHeader',
    'Tooltip', 'Menu', 'Popover', 'Dialog', 'Toast', 'CommandPalette',
    'Badge', 'Spinner', 'Callout', 'EmptyState',
    'List', 'Table', 'FilterBar',
    'Splitter', 'Panel',
    'Message', 'ActivityTimeline', 'StatusLine', 'ApprovalCard', 'FileList', 'ExpertBox', 'Composer', 'ModelPicker', 'ModeMenu', 'Extensions',
    'SettingRow', 'ProviderCard',
    'KnowledgeGraph', 'KnowledgeChange', 'UsedSources',
]

def build_bundle():
    icons = json.load(open(os.path.join(HERE, 'icons.json')))
    groups = json.load(open(os.path.join(HERE, 'icons_groups.json')))
    svg = open(LOGO_SVG).read()
    inner = svg[svg.index('>') + 1: svg.rindex('</svg>')]
    src = open(os.path.join(HERE, 'bundle.src.js')).read()
    # Line 1: namespace and component order (gallery groups in order; page mocks and Cover excluded).
    header = {'format': 4, 'namespace': 'SS', 'components': [{'name': n} for n in ORDER]}
    src = '/* @ds-bundle: ' + json.dumps(header, separators=(',', ':')) + ' */\n' + src
    out = (src.replace('__ICONS__', json.dumps(icons, ensure_ascii=False, separators=(',', ':')))
              .replace('__GROUPS__', json.dumps(groups, ensure_ascii=False, separators=(',', ':')))
              .replace('__LOGO__', json.dumps(inner)))
    for bad in ('</script', '<!--'):
        assert bad not in out.lower(), bad
    open(os.path.join(DS, 'components', 'bundle.js'), 'w').write(out)
    return len(out)

def build_bundle_css():
    comp = open(os.path.join(APP_STYLES, 'components.css')).read()
    body = comp[comp.index('*/') + 2:].lstrip('\n')
    gallery = open(os.path.join(HERE, 'gallery.css')).read()
    head = ('/* ScienceScope components (design system v1, 2026-10-16).\n'
            '   Built from app/ui/styles/components.css (the ss- components the app ships) and\n'
            '   build/gallery.css (the ds- gallery scaffolding). Colours, spacing, radii, shadows,\n'
            '   sizes and type come from tokens.css, which is generated from tokens.json. */\n')
    out = head + FONT_IMPORT + '\n\n' + body.rstrip('\n') + '\n\n' + gallery
    open(os.path.join(DS, 'components', 'bundle.css'), 'w').write(out)
    return len(out)

def prettier(paths):
    bin = os.path.join(ROOT, 'node_modules', '.bin', 'prettier')
    if os.path.exists(bin): subprocess.run([bin, '--log-level', 'warn', '--write', *paths], check=True, cwd=ROOT)
    else: print('prettier not installed (npm ci); app files left unformatted')

def build_app_files():
    t = json.load(open(os.path.join(DS, 'tokens.json')))
    themes = [x['id'] for x in t['color']['themes']]
    first = themes[0]
    def val(tok, theme):
        v = tok['value']
        if isinstance(v, str): return v
        return v.get(theme, v.get(first))
    lines = ['/* ' + GENERATED % 'project/tokens.json' + ' */', ':root {']
    for fam in ('color', 'shadow'):
        for tok in t[fam]['tokens']:
            lines.append(f"  --{tok['name']}: {resolve(val(tok, first))};")
    for fam, block in t.items():
        if fam in ('color', 'shadow', 'type') or not isinstance(block, dict) or 'tokens' not in block: continue
        for tok in block['tokens']:
            lines.append(f"  --{tok['name']}: {tok['value']};")
    for k, stack in t['type']['families'].items():
        lines.append(f'  --font-{k}: {stack};')
    lines.append('}')
    for th in themes[1:]:
        lines.append(f":root[data-theme='{th}'] {{")
        for fam in ('color', 'shadow'):
            for tok in t[fam]['tokens']:
                if val(tok, th) != val(tok, first):
                    lines.append(f"  --{tok['name']}: {resolve(val(tok, th))};")
        lines.append('}')
    for g in t['type']['groups']:
        for st in g['styles']:
            fam = st.get('family', g['family'])
            lines.append(f".{st['name']} {{ font-family: var(--font-{fam}); font-size: {st['fontSize']}; line-height: {st['lineHeight']}; font-weight: {st['fontWeight']}; }}")
    tokens_css = os.path.join(APP_STYLES, 'tokens.css')
    open(tokens_css, 'w').write('\n'.join(lines) + '\n')
    icons = json.load(open(os.path.join(HERE, 'icons.json')))
    js = ['// ' + GENERATED % 'build/icons.json (Lucide 1.49.0, ISC)', '// Inner SVG of each icon on the 24 grid; see app/ui/icons.js.',
          'export const LUCIDE = ' + json.dumps(icons, separators=(',', ': ')) + ';']
    open(APP_ICONS, 'w').write('\n'.join(js) + '\n')
    prettier([tokens_css, APP_ICONS])
    return len(icons)

def resolve(v):
    m = re.fullmatch(r'\{([A-Za-z0-9][A-Za-z0-9_.-]*)\}', v)
    return f'var(--{m.group(1)})' if m else v

def build_tokens_css():
    t = json.load(open(os.path.join(DS, 'tokens.json')))
    themes = [x['id'] for x in t['color']['themes']]
    first = themes[0]
    def val(tok, theme):
        v = tok['value']
        if isinstance(v, str): return v if theme == first else None
        return v.get(theme) if theme in v else (v.get(first) if theme == first else None)
    lines = ['/* ScienceScope — local preview copy compiled from tokens.json */']
    lines.append(f':root, [data-theme="{first}"] {{')
    for fam in ('color', 'shadow'):
        for tok in t[fam]['tokens']:
            lines.append(f"  --{tok['name']}: {resolve(val(tok, first))};")
    lines.append('}')
    for th in themes[1:]:
        lines.append(f'[data-theme="{th}"] {{')
        for fam in ('color', 'shadow'):
            for tok in t[fam]['tokens']:
                v = val(tok, th)
                if v is None: v = val(tok, first)
                lines.append(f"  --{tok['name']}: {resolve(v)};")
        lines.append('}')
    lines.append(':root {')
    for fam, block in t.items():
        if fam in ('color', 'shadow', 'type', 'name', 'version', 'meta') or not isinstance(block, dict): continue
        for tok in block['tokens']:
            lines.append(f"  --{tok['name']}: {tok['value']};")
    for k, stack in t['type']['families'].items():
        lines.append(f'  --font-{k}: {stack};')
    lines.append('}')
    for g in t['type']['groups']:
        for s in g['styles']:
            fam = s.get('family', g['family'])
            lines.append(f".{s['name']} {{ font-family: var(--font-{fam}); font-size: {s['fontSize']}; line-height: {s['lineHeight']}; font-weight: {s['fontWeight']}; }}")
    os.makedirs(TMP, exist_ok=True)
    open(os.path.join(TMP, 'tokens.local.css'), 'w').write('\n'.join(lines) + '\n')
    # Noto Sans SC from the app's dependency when installed; otherwise system fonts.
    noto = os.path.join(ROOT, 'node_modules', '@fontsource-variable', 'noto-sans-sc', 'index.css')
    fonts = "@import url('%s');\n" % pathlib.Path(noto).as_uri() if os.path.exists(noto) else ''
    open(os.path.join(TMP, 'fonts.local.css'), 'w').write(fonts)
    # sanity: unique names across non-type families
    names = []
    for fam, block in t.items():
        if isinstance(block, dict) and 'tokens' in block: names += [x['name'] for x in block['tokens']]
    dup = {n for n in names if names.count(n) > 1}
    assert not dup, dup
    return len(names)

if __name__ == '__main__':
    print('bundle.js bytes', build_bundle())
    print('bundle.css bytes', build_bundle_css())
    print('app icons', build_app_files())
    print('tokens', build_tokens_css())
